// ==========================================================================
// User Directive: Admin Reader Generator Actions
// ==========================================================================
async function handleAdminCreateReader(e) {
    e.preventDefault();

    const name = document.getElementById("genReaderName").value.trim();
    const email = document.getElementById("genReaderEmail").value.trim();
    const customId = document.getElementById("genReaderId").value.trim();
    const password = document.getElementById("genReaderPassword").value.trim();

    // Day 1 email regex check
    const emailRegex = /^[a-zA-Z0-9_+&*-]+(?:\.[a-zA-Z0-9_+&*-]+)*@(?:[a-zA-Z0-9-]+\.)+[a-zA-Z]{2,7}$/;
    if (!emailRegex.test(email)) {
        showToast("Invalid email address. Please provide a valid email.", "error");
        return;
    }

    // Day 1 password length check
    if (password.length < 6) {
        showToast("Password must be at least 6 characters long.", "error");
        return;
    }

    try {
        const res = await fetch("/api/admin/create-reader", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ userId: customId, name, email, password })
        });

        const data = await res.json();
        if (res.ok && data.success) {
            showToast("🎉 Reader account created & activated successfully!", "success");

            // Display credentials box
            const box = document.getElementById("generatedCredBox");
            document.getElementById("dispGenId").textContent = data.reader.userId;
            document.getElementById("dispGenName").textContent = data.reader.name;
            document.getElementById("dispGenEmail").textContent = data.reader.email;
            document.getElementById("dispGenPass").textContent = data.reader.password;
            box.classList.remove("hidden");

            // Reset form
            document.getElementById("adminCreateReaderForm").reset();

            // Refresh readers list
            fetchAdminData();
        } else {
            showToast(data.error || "Failed to create reader.", "error");
        }
    } catch (e) {
        showToast("Network error creating reader account.", "error");
    }
}

function copyGeneratedCreds() {
    const id = document.getElementById("dispGenId").textContent;
    const name = document.getElementById("dispGenName").textContent;
    const email = document.getElementById("dispGenEmail").textContent;
    const pass = document.getElementById("dispGenPass").textContent;

    const text = `Smart Library System - Reader Login Credentials:\nName: ${name}\nReader ID: ${id}\nEmail: ${email}\nPassword: ${pass}\nPortal: http://localhost:8080/`;
    navigator.clipboard.writeText(text).then(() => {
        showToast("📋 Credentials copied to clipboard!", "success");
    }).catch(() => {
        showToast("Failed to copy automatically. Please copy manually.", "info");
    });
}

async function deleteReader(userId) {
    if (!confirm(`Are you sure you want to delete reader ${userId}?`)) return;

    try {
        const res = await fetch(`/api/admin/readers/delete?userId=${encodeURIComponent(userId)}`, {
            method: "DELETE"
        });
        const data = await res.json();
        if (res.ok && data.success) {
            showToast("Reader deleted successfully.", "success");
            fetchAdminData();
        } else {
            showToast(data.error || "Failed to delete reader.", "error");
        }
    } catch (e) {
        showToast("Error deleting reader.", "error");
    }
}

// ==========================================================================
// Rental & Borrow Flow (OOP Polymorphism)
// ==========================================================================
function openBorrowModal(bookId) {
    if (!state.currentUser) {
        showToast("Please sign in first to borrow books.", "error");
        openModal("authModal");
        return;
    }

    const book = state.allBooks.find(b => b.bookId === bookId);
    if (!book) return;

    state.selectedBookForBorrow = book;
    document.getElementById("borrowModalTitle").textContent = book.title;
    document.getElementById("borrowModalAuthor").textContent = `by ${book.author}`;
    document.getElementById("borrowUserIdInput").value = `${state.currentUser.name} (${state.currentUser.userId})`;

    const type = (book.bookType || "PHYSICAL").toUpperCase();
    const typeBadge = document.getElementById("borrowModalType");
    typeBadge.textContent = type;
    typeBadge.className = `book-type-badge ${type === 'EBOOK' ? 'type-ebook' : (type === 'AUDIOBOOK' ? 'type-audiobook' : 'type-physical')}`;

    state.borrowDays = 7;
    document.getElementById("borrowDurationSlider").value = 7;
    document.getElementById("borrowSliderDisplay").textContent = "7 Days";
    document.querySelectorAll(".duration-btn").forEach(b => b.classList.toggle("active", b.getAttribute("data-days") === "7"));

    updateBorrowCalculation();
    openModal("borrowModal");
}

function updateBorrowCalculation() {
    if (!state.selectedBookForBorrow) return;
    const book = state.selectedBookForBorrow;
    const type = (book.bookType || "PHYSICAL").toUpperCase();
    const dailyRate = book.rentalPricePerDay || (type === "EBOOK" ? 10 : (type === "AUDIOBOOK" ? 15 : 20));
    const total = dailyRate * state.borrowDays;

    document.getElementById("borrowModalRatePreview").textContent = `₹${dailyRate.toFixed(2)} / day`;
    document.getElementById("calcDailyRate").textContent = `₹${dailyRate.toFixed(2)}`;
    document.getElementById("calcDuration").textContent = `${state.borrowDays} days`;
    document.getElementById("calcTotal").textContent = `₹${total.toFixed(2)}`;

    // Calculate Due Date
    const dueDate = new Date();
    dueDate.setDate(dueDate.getDate() + state.borrowDays);
    document.getElementById("calcDueDate").textContent = dueDate.toISOString().split("T")[0];

    document.getElementById("calcFormulaNote").textContent =
        `OOP Polymorphism: ${type === 'EBOOK' ? 'EBook' : (type === 'AUDIOBOOK' ? 'AudioBook' : 'PhysicalBook')}.getRentalPrice(${state.borrowDays}) -> ${state.borrowDays} × ₹${dailyRate.toFixed(2)} = ₹${total.toFixed(2)}`;
}

async function confirmBorrowBook() {
    if (!state.selectedBookForBorrow || !state.currentUser) return;

    try {
        const res = await fetch("/api/borrow", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
                userId: state.currentUser.userId,
                bookId: state.selectedBookForBorrow.bookId,
                days: state.borrowDays
            })
        });

        const data = await res.json();
        if (res.ok) {
            closeModal("borrowModal");
            showToast(`✅ Successfully borrowed '${state.selectedBookForBorrow.title}'!`, "success");
            fetchBooks();
            fetchUserActivity();
            fetchStats();
        } else {
            showToast(data.error || "Failed to borrow book.", "error");
        }
    } catch (e) {
        showToast("Network error borrowing book.", "error");
    }
}

