// ==========================================================================
// Book Creation & Management (Admin Only)
// ==========================================================================
async function handleSaveBook(e) {
    e.preventDefault();
    if (!isAdmin()) {
        showToast("Admin access required.", "error");
        return;
    }

    const bookId = document.getElementById("bookIdInput").value.trim();
    const title = document.getElementById("bookTitleInput").value.trim();
    const author = document.getElementById("bookAuthorInput").value.trim();
    const genre = document.getElementById("bookGenreInput").value.trim();
    const bookType = document.getElementById("bookTypeSelect").value;
    const buyPrice = parseFloat(document.getElementById("bookBuyPriceInput").value) || 499;

    const payload = { bookId, title, author, genre, bookType, buyPrice };

    if (bookType === "PHYSICAL") {
        payload.shelfNumber = parseInt(document.getElementById("shelfInput").value, 10) || 100;
    } else if (bookType === "EBOOK") {
        payload.downloadLink = document.getElementById("linkInput").value.trim();
    } else if (bookType === "AUDIOBOOK") {
        payload.narrator = document.getElementById("audioNarratorInput").value.trim() || "Author";
        payload.audioDurationMinutes = parseInt(document.getElementById("audioDurationInput").value, 10) || 180;
        payload.audioStreamUrl = document.getElementById("audioUrlInput").value.trim();
    }

    try {
        const res = await fetch("/api/books", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(payload)
        });

        if (res.ok) {
            closeModal("bookModal");
            showToast(`✅ Book '${title}' saved to catalog!`, "success");
            fetchBooks();
            fetchStats();
        } else {
            const err = await res.json();
            showToast(err.error || "Failed to save book.", "error");
        }
    } catch (e) {
        showToast("Network error saving book.", "error");
    }
}

async function deleteBook(bookId) {
    if (!isAdmin()) return;
    if (!confirm(`Are you sure you want to remove book ${bookId} from catalog?`)) return;

    try {
        const res = await fetch(`/api/books?id=${encodeURIComponent(bookId)}`, {
            method: "DELETE"
        });
        if (res.ok) {
            showToast("Book removed from catalog.", "success");
            fetchBooks();
            fetchStats();
        } else {
            showToast("Failed to delete book.", "error");
        }
    } catch (e) {
        showToast("Error deleting book.", "error");
    }
}

// ==========================================================================
// Authentication (Strict Architecture)
// ==========================================================================
async function handleLoginSubmit(e) {
    e.preventDefault();
    const userId = document.getElementById("loginUserId").value.trim();
    const pass = document.getElementById("loginPassword").value.trim();
    loginUser(userId, pass);
}

async function loginUser(userId, password) {
    try {
        const res = await fetch("/api/auth/login", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ userId, password })
        });

        const data = await res.json();
        if (res.ok && data.success) {
            state.currentUser = data.user;
            localStorage.setItem("sls_user", JSON.stringify(state.currentUser));
            updateUserUI();
            closeModal("authModal");
            showToast(`👋 Welcome back, ${state.currentUser.name} (${state.currentUser.role})!`, "success");

            fetchUserActivity();
            if (isAdmin()) {
                fetchAdminData();
            } else {
                switchTab("catalogTab");
            }
        } else {
            showToast(data.error || "Invalid User ID or Password.", "error");
        }
    } catch (e) {
        showToast("Network error during login.", "error");
    }
}

function logoutUser() {
    state.currentUser = null;
    localStorage.removeItem("sls_user");
    updateUserUI();
    showToast("Signed out successfully.", "info");
    switchTab("catalogTab");
}

// ==========================================================================
// Storage Mode Toggle (In-Memory / MySQL)
// ==========================================================================
async function toggleDatabaseMode() {
    const isCurrentlyDb = document.getElementById("dbModeText").textContent.includes("MySQL");
    const targetMode = !isCurrentlyDb;

    try {
        const res = await fetch("/api/config/db", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ enable: targetMode })
        });

        const data = await res.json();
        showToast(data.message || (targetMode ? "Switched to MySQL Database" : "Switched to In-Memory mode"), data.success ? "success" : "info");
        fetchHealth();
        fetchBooks();
        fetchStats();
    } catch (e) {
        showToast("Unable to toggle database mode.", "error");
    }
}

// ==========================================================================
// Modal & Toast Helpers
// ==========================================================================
function openModal(modalId) {
    const modal = document.getElementById(modalId);
    if (modal) modal.classList.remove("hidden");
}

function closeModal(modalId) {
    const modal = document.getElementById(modalId);
    if (modal) modal.classList.add("hidden");
}

function showToast(message, type = "info") {
    const container = document.getElementById("toastContainer");
    const toast = document.createElement("div");
    toast.className = `toast toast-${type}`;

    let icon = "ℹ️";
    if (type === "success") icon = "✅";
    if (type === "error") icon = "❌";

    toast.innerHTML = `<span>${icon}</span><span>${escapeHtml(message)}</span>`;
    container.appendChild(toast);

    setTimeout(() => {
        toast.style.opacity = "0";
        toast.style.transform = "translateY(10px)";
        toast.style.transition = "all 0.25s ease";
        setTimeout(() => toast.remove(), 250);
    }, 4000);
}

function escapeHtml(str) {
    if (!str) return "";
    return String(str)
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#039;");
}
